from datetime import datetime, timezone
import json, subprocess

def gh_json(args):
    out = subprocess.check_output(["gh", *args], text=True)
    return json.loads(out)

branch = gh_json(["api", "repos/garmin/meta-lts-collab/branches/kirkstone"])
tip_sha = branch["commit"]["sha"]
tip_date = branch["commit"]["commit"]["committer"]["date"]
tip_msg = branch["commit"]["commit"]["message"].splitlines()[0]

compare = gh_json([
    "api",
    "repos/garmin/meta-lts-collab/compare/e127ed67e74ca6b7e0fdc6cbda572302886c00a0...kirkstone",
])

tree = gh_json(["api", f"repos/garmin/meta-lts-collab/git/trees/{tip_sha}?recursive=1"])
lws_paths = [
    item["path"]
    for item in tree.get("tree", [])
    if "libwebsockets" in item["path"].lower()
    or "19773" in item["path"].lower()
    or "zdi-26-590" in item["path"].lower()
]

queries = ["libwebsockets", "CVE-2026-19773", "ZDI-26-590", "824151862", "0c6cef092", "zdi-can-31036"]
pr_matches = {}
issue_matches = {}
for q in queries:
    prs = gh_json([
        "pr", "list", "--repo", "garmin/meta-lts-collab", "--state", "all",
        "--limit", "100", "--search", q,
        "--json", "number,title,state,baseRefName,headRefName,url,createdAt,closedAt,mergedAt",
    ])
    issues = gh_json([
        "issue", "list", "--repo", "garmin/meta-lts-collab", "--state", "all",
        "--limit", "100", "--search", q,
        "--json", "number,title,state,url,createdAt,closedAt",
    ])
    pr_matches[q] = prs
    issue_matches[q] = issues

report = {
    "checked_at": datetime.now(timezone.utc).isoformat(),
    "repository": "garmin/meta-lts-collab",
